insert into public.tests (id,title,class_level,subject,chapter,duration_minutes,total_marks,questions,attempt_limit,is_published) values ('test-c9-renaissance-60','{"hi":"कक्षा 9 साप्ताहिक ऑनलाइन टेस्ट - इतिहास (अध्याय 1–3)","en":"Class 9th Weekly Online Test - History (Chapters 1–3)"}'::jsonb,'9','History','अध्याय 1: सामाजिक एवं सांस्कृतिक पुनर्जागरण · अध्याय 2: राष्ट्रीय चेतना के तत्व · अध्याय 3: उदारवादी एवं राष्ट्रवादी (1857–1919)',60,60,'[{"id":"c9-q1","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","question":{"hi":"ब्रह्म समाज की स्थापना किसने की थी?","en":"Who founded the Brahmo Samaj?"},"options":{"hi":["स्वामी दयानंद सरस्वती","राजा राममोहन राय","स्वामी विवेकानंद","ज्योतिबा फुले"],"en":["Swami Dayanand Saraswati","Raja Ram Mohan Roy","Swami Vivekananda","Jyotirao Phule"]}},{"id":"c9-q2","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","question":{"hi":"राजा राममोहन राय ने ब्रह्म समाज की स्थापना कब की थी?","en":"When was Brahmo Samaj founded by Raja Ram Mohan Roy?"},"options":{"hi":["1818 ई.","1828 ई.","1857 ई.","1875 ई."],"en":["1818 AD","1828 AD","1857 AD","1875 AD"]}},{"id":"c9-q3","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","question":{"hi":"सती प्रथा के विरोध में प्रमुख भूमिका किसने निभाई?","en":"Who played a key role against the practice of Sati?"},"options":{"hi":["राजा राममोहन राय","बाल गंगाधर तिलक","लाला लाजपत राय","गोपाल कृष्ण गोखले"],"en":["Raja Ram Mohan Roy","Bal Gangadhar Tilak","Lala Lajpat Rai","Gopal Krishna Gokhale"]}},{"id":"c9-q4","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","question":{"hi":"आर्य समाज की स्थापना किसने की थी?","en":"Who founded the Arya Samaj?"},"options":{"hi":["स्वामी विवेकानंद","स्वामी दयानंद सरस्वती","राजा राममोहन राय","ज्योतिबा फुले"],"en":["Swami Vivekananda","Swami Dayanand Saraswati","Raja Ram Mohan Roy","Jyotirao Phule"]}},{"id":"c9-q5","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","question":{"hi":"आर्य समाज की स्थापना किस वर्ष हुई थी?","en":"In which year was Arya Samaj founded?"},"options":{"hi":["1828 ई.","1856 ई.","1875 ई.","1897 ई."],"en":["1828 AD","1856 AD","1875 AD","1897 AD"]}},{"id":"c9-q6","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","question":{"hi":"प्रार्थना समाज की स्थापना किस वर्ष हुई थी?","en":"In which year was Prarthana Samaj founded?"},"options":{"hi":["1840 ई.","1867 ई.","1875 ई.","1893 ई."],"en":["1840 AD","1867 AD","1875 AD","1893 AD"]}},{"id":"c9-q7","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","question":{"hi":"प्रार्थना समाज की स्थापना से संबंधित प्रमुख समाज सुधारक कौन थे?","en":"Who was the key social reformer associated with the founding of Prarthana Samaj?"},"options":{"hi":["आत्माराम पांडुरंग","महात्मा गांधी","सुभाष चंद्र बोस","भगत सिंह"],"en":["Dr. Atmaram Pandurang","Mahatma Gandhi","Subhash Chandra Bose","Bhagat Singh"]}},{"id":"c9-q8","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","question":{"hi":"रामकृष्ण मिशन की स्थापना किसने की थी?","en":"Who founded the Ramakrishna Mission?"},"options":{"hi":["रामकृष्ण परमहंस","स्वामी विवेकानंद","स्वामी दयानंद सरस्वती","केशवचंद्र सेन"],"en":["Ramakrishna Paramahamsa","Swami Vivekananda","Swami Dayanand Saraswati","Keshab Chandra Sen"]}},{"id":"c9-q9","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","question":{"hi":"रामकृष्ण मिशन की स्थापना कब हुई थी?","en":"When was Ramakrishna Mission founded?"},"options":{"hi":["1875 ई.","1880 ई.","1897 ई.","1905 ई."],"en":["1875 AD","1880 AD","1897 AD","1905 AD"]}},{"id":"c9-q10","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","question":{"hi":"रामकृष्ण मिशन का मुख्य उद्देश्य क्या था?","en":"What was the primary objective of Ramakrishna Mission?"},"options":{"hi":["केवल राजनीतिक स्वतंत्रता","आध्यात्मिक उत्थान एवं मानव सेवा","विदेशी व्यापार बढ़ाना","अंग्रेजी शासन का विस्तार"],"en":["Only political independence","Spiritual upliftment and service to humanity","Promoting foreign trade","Expansion of British rule"]}},{"id":"c9-q11","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","question":{"hi":"स्वामी विवेकानंद ने शिकागो विश्व धर्म सम्मेलन में किस वर्ष भाग लिया?","en":"In which year did Swami Vivekananda participate in the World Parliament of Religions in Chicago?"},"options":{"hi":["1885 ई.","1893 ई.","1897 ई.","1905 ई."],"en":["1885 AD","1893 AD","1897 AD","1905 AD"]}},{"id":"c9-q12","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","question":{"hi":"आर्य समाज का प्रमुख नारा कौन-सा था?","en":"Which was the principal slogan of Arya Samaj?"},"options":{"hi":["करो या मरो","वेदों की ओर लौटो","जय जवान जय किसान","दिल्ली चलो"],"en":["Do or Die","Back to the Vedas","Jai Jawan Jai Kisan","Chalo Delhi"]}},{"id":"c9-q13","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","question":{"hi":"विधवा पुनर्विवाह के समर्थन में प्रमुख भूमिका किसने निभाई?","en":"Who played a foremost role in advocating for widow remarriage?"},"options":{"hi":["ईश्वरचंद्र विद्यासागर","बाल गंगाधर तिलक","लाला लाजपत राय","बिपिन चंद्र पाल"],"en":["Ishwar Chandra Vidyasagar","Bal Gangadhar Tilak","Lala Lajpat Rai","Bipin Chandra Pal"]}},{"id":"c9-q14","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","question":{"hi":"जातिगत भेदभाव के विरोध से संबंधित प्रमुख समाज सुधारक कौन थे?","en":"Who among the following was a prominent social reformer fighting against caste discrimination?"},"options":{"hi":["ज्योतिबा फुले","लॉर्ड कर्जन","लॉर्ड डलहौजी","लॉर्ड रिपन"],"en":["Jyotirao Phule","Lord Curzon","Lord Dalhousie","Lord Ripon"]}},{"id":"c9-q15","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","question":{"hi":"सत्यशोधक समाज की स्थापना किसने की थी?","en":"Who founded the Satyashodhak Samaj?"},"options":{"hi":["महात्मा गांधी","ज्योतिबा फुले","स्वामी विवेकानंद","राजा राममोहन राय"],"en":["Mahatma Gandhi","Jyotirao Phule","Swami Vivekananda","Raja Ram Mohan Roy"]}},{"id":"c9-q16","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","question":{"hi":"डॉ. भीमराव अंबेडकर ने किसके विरुद्ध संघर्ष किया?","en":"Against what did Dr. B.R. Ambedkar primarily wage his struggle?"},"options":{"hi":["सामाजिक असमानता एवं जातिगत भेदभाव","आधुनिक शिक्षा","महिला शिक्षा","औद्योगिक विकास"],"en":["Social inequality and caste discrimination","Modern education","Women education","Industrial development"]}},{"id":"c9-q17","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","question":{"hi":"भारतीय पुनर्जागरण का प्रमुख उद्देश्य क्या था?","en":"What was the main goal of the Indian Renaissance?"},"options":{"hi":["सामाजिक कुरीतियों को बढ़ावा देना","सामाजिक एवं धार्मिक सुधार करना","शिक्षा का विरोध करना","जातिगत भेदभाव बढ़ाना"],"en":["Promoting social evils","Undertaking social and religious reforms","Opposing modern education","Increasing caste divisions"]}},{"id":"c9-q18","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","question":{"hi":"महिला शिक्षा के प्रसार का संबंध किससे है?","en":"The promotion of women''s education is directly related to which movement?"},"options":{"hi":["सामाजिक सुधार आंदोलन","साम्राज्यवादी विस्तार","सैन्य संगठन","विदेशी व्यापार"],"en":["Social reform movements","Imperialist expansion","Military organization","Foreign commerce"]}},{"id":"c9-q19","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","question":{"hi":"भारतीय समाज सुधार आंदोलनों ने किस प्रथा का विरोध किया?","en":"Which practice was strongly opposed by Indian social reform movements?"},"options":{"hi":["महिला शिक्षा","सती प्रथा","आधुनिक शिक्षा","सामाजिक समानता"],"en":["Female education","Sati practice","Modern scientific education","Social equality"]}},{"id":"c9-q20","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","question":{"hi":"सामाजिक एवं सांस्कृतिक पुनर्जागरण का प्रमुख परिणाम क्या था?","en":"What was the primary outcome of the socio-cultural renaissance?"},"options":{"hi":["सामाजिक जागरूकता में वृद्धि","शिक्षा का अंत","जातिगत भेदभाव का समर्थन","सामाजिक सुधारों का विरोध"],"en":["Growth in social and political awareness","Demise of education","Support for caste evils","Resistance to reforms"]}},{"id":"c9-q21","chapter":"अध्याय 2: राष्ट्रीय चेतना के तत्व","question":{"hi":"भारत में राष्ट्रीय चेतना के विकास में किसका योगदान था?","en":"What contributed significantly to the growth of national consciousness in India?"},"options":{"hi":["सामाजिक एवं धार्मिक सुधार आंदोलन","केवल विदेशी व्यापार","केवल सैन्य गतिविधियाँ","केवल प्राकृतिक आपदाएँ"],"en":["Socio-religious reform movements","Only overseas trade","Only military operations","Only natural calamities"]}},{"id":"c9-q22","chapter":"अध्याय 2: राष्ट्रीय चेतना के तत्व","question":{"hi":"स्वामी दयानंद सरस्वती ने किस संगठन की स्थापना की?","en":"Which organization was founded by Swami Dayanand Saraswati?"},"options":{"hi":["ब्रह्म समाज","आर्य समाज","प्रार्थना समाज","सत्यशोधक समाज"],"en":["Brahmo Samaj","Arya Samaj","Prarthana Samaj","Satyashodhak Samaj"]}},{"id":"c9-q23","chapter":"अध्याय 2: राष्ट्रीय चेतना के तत्व","question":{"hi":"स्वामी विवेकानंद ने किस बात पर विशेष बल दिया?","en":"What did Swami Vivekananda especially emphasize?"},"options":{"hi":["मानव सेवा एवं आध्यात्मिक विकास","जातिगत भेदभाव","सामाजिक असमानता","शिक्षा का विरोध"],"en":["Humanitarian service and spiritual growth","Caste discrimination","Social disparity","Opposition to literacy"]}},{"id":"c9-q24","chapter":"अध्याय 2: राष्ट्रीय चेतना के तत्व","question":{"hi":"भारतीय राष्ट्रीय चेतना के विकास में समाचार-पत्रों की क्या भूमिका थी?","en":"What role did newspapers play in cultivating Indian national consciousness?"},"options":{"hi":["जनता में जागरूकता फैलाना","शिक्षा समाप्त करना","सुधारों का विरोध","विदेशी शासन मजबूत करना"],"en":["Spreading civic awareness among masses","Ending schooling","Resisting reforms","Strengthening colonial rule"]}},{"id":"c9-q25","chapter":"अध्याय 2: राष्ट्रीय चेतना के तत्व","question":{"hi":"आर्थिक राष्ट्रवाद से संबंधित प्रमुख विचारक कौन थे?","en":"Who was the foremost thinker associated with Indian Economic Nationalism?"},"options":{"hi":["दादाभाई नौरोजी","स्वामी विवेकानंद","रामकृष्ण परमहंस","राजा राममोहन राय"],"en":["Dadabhai Naoroji","Swami Vivekananda","Ramakrishna Paramahamsa","Raja Ram Mohan Roy"]}},{"id":"c9-q26","chapter":"अध्याय 2: राष्ट्रीय चेतना के तत्व","question":{"hi":"दादाभाई नौरोजी का प्रसिद्ध आर्थिक विचार किससे संबंधित था?","en":"Dadabhai Naoroji''s famous economic thesis was related to what?"},"options":{"hi":["धन-निष्कासन सिद्धांत","पंचवर्षीय योजना","हरित क्रांति","श्वेत क्रांति"],"en":["Drain of Wealth Theory","Five Year Plans","Green Revolution","White Revolution"]}},{"id":"c9-q27","chapter":"अध्याय 2: राष्ट्रीय चेतना के तत्व","question":{"hi":"''Poverty and Un-British Rule in India'' के लेखक कौन थे?","en":"Who was the author of the book ''Poverty and Un-British Rule in India''?"},"options":{"hi":["दादाभाई नौरोजी","महात्मा गांधी","जवाहरलाल नेहरू","बाल गंगाधर तिलक"],"en":["Dadabhai Naoroji","Mahatma Gandhi","Jawaharlal Nehru","Bal Gangadhar Tilak"]}},{"id":"c9-q28","chapter":"अध्याय 2: राष्ट्रीय चेतना के तत्व","question":{"hi":"भारत में 1857 का विद्रोह किसके विरुद्ध हुआ?","en":"Against whom was the 1857 revolt in India waged?"},"options":{"hi":["ब्रिटिश शासन","फ्रांसीसी शासन","पुर्तगाली शासन","डच शासन"],"en":["British Rule","French Rule","Portuguese Rule","Dutch Rule"]}},{"id":"c9-q29","chapter":"अध्याय 2: राष्ट्रीय चेतना के तत्व","question":{"hi":"1857 के विद्रोह ने भारतीयों में किस भावना को मजबूत किया?","en":"Which sentiment was strengthened among Indians by the 1857 revolt?"},"options":{"hi":["राष्ट्रीय चेतना","विदेशी शासन का समर्थन","सामाजिक निष्क्रियता","शिक्षा का विरोध"],"en":["National Consciousness","Support for British rule","Social passivity","Anti-learning bias"]}},{"id":"c9-q30","chapter":"अध्याय 2: राष्ट्रीय चेतना के तत्व","question":{"hi":"भारतीय राष्ट्रीय चेतना के विकास में किसका योगदान था?","en":"Who contributed to the development of Indian national consciousness?"},"options":{"hi":["सामाजिक सुधारक","समाचार-पत्र","साहित्यकार","उपर्युक्त सभी"],"en":["Social reformers","Newspapers & journalism","Literary writers & poets","All of the above"]}},{"id":"c9-q31","chapter":"अध्याय 2: राष्ट्रीय चेतना के तत्व","question":{"hi":"भारतीय समाचार-पत्रों ने मुख्यतः किस कार्य में योगदान दिया?","en":"What was the primary contribution of Indian newspapers during this period?"},"options":{"hi":["राजनीतिक एवं सामाजिक जागरूकता","केवल मनोरंजन","विदेशी शासन का प्रचार","शिक्षा का विरोध"],"en":["Political and social awakening","Mere recreation","Pro-colonial propaganda","Opposing modern schools"]}},{"id":"c9-q32","chapter":"अध्याय 2: राष्ट्रीय चेतना के तत्व","question":{"hi":"राष्ट्रीय साहित्य का प्रमुख उद्देश्य क्या था?","en":"What was the main purpose of Indian nationalist literature?"},"options":{"hi":["राष्ट्रीय भावना का विकास","सामाजिक असमानता बढ़ाना","विदेशी शासन स्थायी बनाना","जनता को राजनीति से दूर रखना"],"en":["Promoting patriotic and national sentiment","Increasing social rift","Making British rule permanent","Depoliticizing masses"]}},{"id":"c9-q33","chapter":"अध्याय 2: राष्ट्रीय चेतना के तत्व","question":{"hi":"राष्ट्रवादी विचारों के प्रसार में किन पत्र-पत्रिकाओं ने भूमिका निभाई?","en":"Which publications played a key role in propagating nationalist ideas?"},"options":{"hi":["केवल अंग्रेजी","केवल फ्रेंच","भारतीय भाषाएँ एवं अंग्रेजी","केवल पुर्तगाली"],"en":["Only English","Only French","Indian regional languages and English","Only Portuguese"]}},{"id":"c9-q34","chapter":"अध्याय 2: राष्ट्रीय चेतना के तत्व","question":{"hi":"ब्रिटिश शासन की आर्थिक नीतियों की आलोचना किसने की?","en":"Who systematically critiqued the economic policies of British colonial rule?"},"options":{"hi":["दादाभाई नौरोजी","रामकृष्ण परमहंस","स्वामी विवेकानंद","स्वामी रामकृष्ण"],"en":["Dadabhai Naoroji","Ramakrishna Paramahamsa","Swami Vivekananda","Swami Ramkrishna"]}},{"id":"c9-q35","chapter":"अध्याय 2: राष्ट्रीय चेतना के तत्व","question":{"hi":"बहिष्कार की नीति का उद्देश्य क्या था?","en":"What was the core objective of the Boycott policy?"},"options":{"hi":["विदेशी वस्तुओं के उपयोग को कम करना","विदेशी वस्तुओं की बिक्री बढ़ाना","भारतीय उद्योग बंद करना","भारतीय शिक्षा समाप्त करना"],"en":["Curtailing usage of foreign/British goods","Promoting imported luxury goods","Shutting down Indian factories","Dismantling schools"]}},{"id":"c9-q36","chapter":"अध्याय 2: राष्ट्रीय चेतना के तत्व","question":{"hi":"स्वदेशी आंदोलन का प्रमुख उद्देश्य क्या था?","en":"What was the primary goal of the Swadeshi Movement?"},"options":{"hi":["स्वदेशी वस्तुओं को प्रोत्साहित करना","विदेशी वस्तुओं को बढ़ावा देना","भारतीय उद्योगों का विरोध","जागरूकता समाप्त करना"],"en":["Encouraging domestic Indian goods and industries","Promoting British manufacturers","Opposing Indian craft","Supressing awareness"]}},{"id":"c9-q37","chapter":"अध्याय 2: राष्ट्रीय चेतना के तत्व","question":{"hi":"राष्ट्रीय चेतना के विकास में साहित्य ने कैसे योगदान दिया?","en":"How did literature contribute to fostering national consciousness?"},"options":{"hi":["राष्ट्रीय विचारों का प्रसार करके","राजनीतिक जागरूकता समाप्त करके","सुधारों का विरोध करके","जनता को निष्क्रिय बनाकर"],"en":["By disseminating patriotic ideas","By abolishing civic awareness","By opposing reforms","By encouraging docility"]}},{"id":"c9-q38","chapter":"अध्याय 2: राष्ट्रीय चेतना के तत्व","question":{"hi":"सामाजिक सुधार आंदोलनों का महत्व क्या था?","en":"What was the historical significance of socio-religious reform movements?"},"options":{"hi":["सामाजिक कुरीतियों के विरुद्ध जागरूकता","जातिगत भेदभाव का विस्तार","शिक्षा का विरोध","महिला अधिकारों का विरोध"],"en":["Awareness against retrograde social evils","Deepening caste hatred","Opposing modern science","Denying women equality"]}},{"id":"c9-q39","chapter":"अध्याय 2: राष्ट्रीय चेतना के तत्व","question":{"hi":"राष्ट्रीय चेतना का विकास किस प्रक्रिया से जुड़ा था?","en":"National consciousness development was linked with which process?"},"options":{"hi":["सामाजिक, आर्थिक एवं राजनीतिक जागरूकता","केवल सैन्य विकास","केवल कृषि उत्पादन","केवल विदेशी व्यापार"],"en":["Socio-economic and political awakening","Only military equipment","Only crop harvests","Only foreign imports"]}},{"id":"c9-q40","chapter":"अध्याय 2: राष्ट्रीय चेतना के तत्व","question":{"hi":"राष्ट्रीय चेतना का प्रमुख परिणाम क्या था?","en":"What was the crowning achievement/result of rising national consciousness?"},"options":{"hi":["राष्ट्रीय एकता एवं स्वतंत्रता की भावना को बल","विदेशी शासन का स्थायी समर्थन","सुधारों का अंत","राष्ट्रीय भावना कमजोर होना"],"en":["Strengthening of national unity and freedom impulse","Perpetual submission to empire","Cessation of reforms","Weakening patriotic bond"]}},{"id":"c9-q41","chapter":"अध्याय 3: उदारवादी एवं राष्ट्रवादी (1857–1919)","question":{"hi":"भारतीय राष्ट्रीय कांग्रेस की स्थापना किस वर्ष हुई?","en":"In which year was the Indian National Congress founded?"},"options":{"hi":["1857 ई.","1885 ई.","1905 ई.","1919 ई."],"en":["1857 AD","1885 AD","1905 AD","1919 AD"]}},{"id":"c9-q42","chapter":"अध्याय 3: उदारवादी एवं राष्ट्रवादी (1857–1919)","question":{"hi":"भारतीय राष्ट्रीय कांग्रेस की स्थापना में प्रमुख भूमिका किसने निभाई?","en":"Who played the pivotal role in the founding of the Indian National Congress?"},"options":{"hi":["ए. ओ. ह्यूम","महात्मा गांधी","भगत सिंह","सुभाष चंद्र बोस"],"en":["Allan Octavian Hume (A.O. Hume)","Mahatma Gandhi","Bhagat Singh","Subhash Chandra Bose"]}},{"id":"c9-q43","chapter":"अध्याय 3: उदारवादी एवं राष्ट्रवादी (1857–1919)","question":{"hi":"कांग्रेस के प्रथम अधिवेशन की अध्यक्षता किसने की?","en":"Who presided over the very first session of the Indian National Congress?"},"options":{"hi":["दादाभाई नौरोजी","डब्ल्यू. सी. बनर्जी","बाल गंगाधर तिलक","गोपाल कृष्ण गोखले"],"en":["Dadabhai Naoroji","Womesh Chandra Bonnerjee (W.C. Bonnerjee)","Bal Gangadhar Tilak","Gopal Krishna Gokhale"]}},{"id":"c9-q44","chapter":"अध्याय 3: उदारवादी एवं राष्ट्रवादी (1857–1919)","question":{"hi":"कांग्रेस का पहला अधिवेशन कहाँ हुआ?","en":"Where was the first session of Congress held?"},"options":{"hi":["कल