insert into public.tests (id,title,class_level,subject,chapter,duration_minutes,total_marks,questions,attempt_limit,is_published) values ('nmms-class8-history-chapter1-40','{"hi":"NMMS कक्षा 8 — इतिहास अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","en":"NMMS Class 8 — History Chapter 1: Tracing Changes Through a Thousand Years"}'::jsonb,'8','History','इतिहास अध्याय 1: एक हजार वर्षों में हुए परिवर्तन',40,40,'[{"id":"nmms-c8-h1-q1","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"एक हजार वर्षों में हुए परिवर्तन अध्याय मुख्य रूप से किस काल से संबंधित है?","en":"Which period is mainly covered in the chapter ''Tracing Changes Through a Thousand Years''?"},"options":{"hi":["500–1000 ईस्वी","700–1750 ईस्वी","1750–1947 ईस्वी","1947–2020 ईस्वी"],"en":["500–1000 CE","700–1750 CE","1750–1947 CE","1947–2020 CE"]}},{"id":"nmms-c8-h1-q2","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"1154 ईस्वी में विश्व का मानचित्र बनाने वाला अरब भूगोलवेत्ता कौन था?","en":"Which Arab geographer prepared a world map in 1154 CE?"},"options":{"hi":["इब्न बतूता","अमीर खुसरो","अल-इदरीसी","अबुल फ़ज़ल"],"en":["Ibn Battuta","Amir Khusrau","Al-Idrisi","Abul Fazl"]}},{"id":"nmms-c8-h1-q3","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"अल-इदरीसी का प्रसिद्ध मानचित्र किस वर्ष तैयार किया गया था?","en":"In which year was Al-Idrisi''s famous map prepared?"},"options":{"hi":["1000 ईस्वी","1154 ईस्वी","1318 ईस्वी","1720 ईस्वी"],"en":["1000 CE","1154 CE","1318 CE","1720 CE"]}},{"id":"nmms-c8-h1-q4","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"मानचित्रकार किसे कहते हैं?","en":"Who is called a cartographer?"},"options":{"hi":["सिक्कों का अध्ययन करने वाला","कविता लिखने वाला","मानचित्र बनाने वाला","अभिलेखों का अध्ययन करने वाला"],"en":["A person who studies coins","A person who writes poetry","A person who makes maps","A person who studies inscriptions"]}},{"id":"nmms-c8-h1-q5","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"अल-इदरीसी के भारतीय उपमहाद्वीप के मानचित्र की एक विशेषता क्या थी?","en":"What was one feature of Al-Idrisi''s map of the Indian subcontinent?"},"options":{"hi":["उत्तर ऊपर दिखाया गया था","दक्षिण भारत उस स्थान पर दिखाया गया था जहाँ सामान्यतः उत्तर भारत होता है","भारत को नहीं दिखाया गया था","केवल हिमालय दिखाया गया था"],"en":["North was shown at the top","South India appeared where north India is usually shown","India was not shown","Only the Himalayas were shown"]}},{"id":"nmms-c8-h1-q6","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"अध्याय में उल्लिखित बाद का मानचित्र लगभग किस समय तैयार किया गया था?","en":"Around when was the later map mentioned in the chapter prepared?"},"options":{"hi":["900 के दशक में","1150 के दशक में","1400 के दशक में","1720 के दशक में"],"en":["The 900s","The 1150s","The 1400s","The 1720s"]}},{"id":"nmms-c8-h1-q7","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"बाद के मानचित्रों में तटीय क्षेत्रों का विवरण अधिक स्पष्ट क्यों था?","en":"Why were coastal areas shown more clearly on later maps?"},"options":{"hi":["नाविकों और व्यापारियों को तटीय क्षेत्रों की बेहतर जानकारी थी","पहले तटीय क्षेत्र नहीं थे","सभी आंतरिक क्षेत्र निर्जन थे","मानचित्र बनाना प्रतिबंधित था"],"en":["Sailors and traders knew coastal areas better","Coastal areas did not exist earlier","All inland areas were uninhabited","Map-making was prohibited"]}},{"id":"nmms-c8-h1-q8","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"निम्नलिखित में से कौन-कौन ऐतिहासिक स्रोत हैं?","en":"Which of the following are historical sources?"},"options":{"hi":["सिक्के","अभिलेख","पांडुलिपियाँ","उपर्युक्त सभी"],"en":["Coins","Inscriptions","Manuscripts","All of the above"]}},{"id":"nmms-c8-h1-q9","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"पांडुलिपि क्या होती है?","en":"What is a manuscript?"},"options":{"hi":["हाथ से लिखी गई सामग्री","मुद्रित समाचार-पत्र","आधुनिक फोटो","मशीन से बनाया गया मानचित्र"],"en":["A hand-written document","A printed newspaper","A modern photograph","A machine-made map"]}},{"id":"nmms-c8-h1-q10","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"मध्यकाल में पांडुलिपियों की हाथ से नकल कौन करता था?","en":"Who copied manuscripts by hand in the medieval period?"},"options":{"hi":["मानचित्रकार","लिपिक","सैनिक","व्यापारी"],"en":["Cartographers","Scribes","Soldiers","Traders"]}},{"id":"nmms-c8-h1-q11","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"एक ही पांडुलिपि की अलग-अलग प्रतियों में अंतर क्यों हो सकता है?","en":"Why might different copies of the same manuscript vary?"},"options":{"hi":["नकल करते समय लिपिक परिवर्तन कर सकते थे","सभी पांडुलिपियाँ मशीन से छपती थीं","इतिहासकार पांडुलिपियाँ नहीं पढ़ते थे","पांडुलिपियों में केवल चित्र होते थे"],"en":["Scribes could introduce changes while copying","All manuscripts were machine-printed","Historians did not read manuscripts","Manuscripts contained only pictures"]}},{"id":"nmms-c8-h1-q12","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"अभिलेखागार क्या है?","en":"What is an archive?"},"options":{"hi":["ऐतिहासिक दस्तावेजों और अभिलेखों को सुरक्षित रखने का स्थान","फसल उगाने का स्थान","सैनिक प्रशिक्षण केंद्र","बाजार"],"en":["A place where historical documents and records are preserved","A place for growing crops","A military training centre","A market"]}},{"id":"nmms-c8-h1-q13","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"इस काल में कागज पर सामान्यतः क्या लिखा जाता था?","en":"What was commonly written on paper during this period?"},"options":{"hi":["पत्र और वृत्तांत","याचिकाएँ और न्यायिक अभिलेख","हिसाब-किताब और कर संबंधी विवरण","उपर्युक्त सभी"],"en":["Letters and chronicles","Petitions and judicial records","Accounts and tax details","All of the above"]}},{"id":"nmms-c8-h1-q14","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"अध्याय में उल्लिखित चौदहवीं शताब्दी का इतिहासकार कौन था?","en":"Which fourteenth-century historian is mentioned in the chapter?"},"options":{"hi":["जियाउद्दीन बरनी","अल-इदरीसी","जेम्स मिल","गिलॉम दे लिस्ले"],"en":["Ziyauddin Barani","Al-Idrisi","James Mill","Guillaume de L''Isle"]}},{"id":"nmms-c8-h1-q15","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"इतिहासकारों के संबंध में कौन-सा कथन सही है?","en":"Which statement about historians is correct?"},"options":{"hi":["वे केवल मौखिक कहानियों पर निर्भर रहते हैं","वे विभिन्न स्रोतों का अध्ययन करके उनकी ऐतिहासिक संदर्भ में व्याख्या करते हैं","वे कभी पांडुलिपियों की तुलना नहीं करते","वे केवल आधुनिक घटनाओं का अध्ययन करते हैं"],"en":["They rely only on oral stories","They study different sources and interpret them in historical context","They never compare manuscripts","They study only modern events"]}},{"id":"nmms-c8-h1-q16","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"तेरहवीं शताब्दी में उत्तरी भारत के एक विशेष क्षेत्र के लिए हिंदुस्तान शब्द का प्रयोग किसने किया?","en":"Who used the term Hindustan for a particular region of northern India in the thirteenth century?"},"options":{"hi":["बाबर","मिनहाज-ए-सिराज","अमीर खुसरो","अबुल फ़ज़ल"],"en":["Babur","Minhaj-i-Siraj","Amir Khusrau","Abul Fazl"]}},{"id":"nmms-c8-h1-q17","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"मिनहाज-ए-सिराज के प्रयोग में हिंदुस्तान मुख्य रूप से किन क्षेत्रों को दर्शाता था?","en":"Which areas did Hindustan mainly refer to in Minhaj-i-Siraj''s usage?"},"options":{"hi":["पंजाब, हरियाणा और गंगा-यमुना क्षेत्र","केवल दक्षिण भारत","केवल बंगाल","संपूर्ण एशिया"],"en":["Punjab, Haryana and the Ganga-Yamuna region","Only south India","Only Bengal","All of Asia"]}},{"id":"nmms-c8-h1-q18","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"सोलहवीं शताब्दी के आरंभ में बाबर ने हिंदुस्तान शब्द का प्रयोग किस संदर्भ में किया?","en":"In what context did Babur use the term Hindustan in the early sixteenth century?"},"options":{"hi":["केवल दिल्ली के लिए","केवल पंजाब के लिए","उपमहाद्वीप के भूगोल, जीव-जंतुओं और संस्कृति के वर्णन के लिए","केवल हिमालय के लिए"],"en":["Only for Delhi","Only for Punjab","To describe the subcontinent''s geography, flora, fauna and culture","Only for the Himalayas"]}},{"id":"nmms-c8-h1-q19","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"मध्यकालीन संदर्भ में किसी व्यक्ति को विदेशी किस अर्थ में माना जा सकता था?","en":"In the medieval context, in what sense could a person be considered a ''foreigner''?"},"options":{"hi":["केवल दूसरे देश का नागरिक","ऐसा अपरिचित व्यक्ति जो किसी विशेष गाँव या समाज का हिस्सा नहीं था","केवल राजा","केवल व्यापारी"],"en":["Only a citizen of another country","An unfamiliar person who was not part of a particular village or community","Only a king","Only a trader"]}},{"id":"nmms-c8-h1-q20","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"एक नगरवासी वनवासी को विदेशी क्यों मान सकता था?","en":"Why might a town-dweller consider a forest-dweller a foreigner?"},"options":{"hi":["वे हमेशा अलग देशों के होते थे","उनकी सामाजिक और सांस्कृतिक पृष्ठभूमि अलग हो सकती थी","वनवासी बोल नहीं सकते थे","वनवासी हमेशा शासक होते थे"],"en":["They always came from different countries","Their social and cultural backgrounds could be different","Forest-dwellers could not speak","Forest-dwellers were always rulers"]}},{"id":"nmms-c8-h1-q21","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"राजपूत शब्द की उत्पत्ति किस संस्कृत शब्द से हुई है?","en":"From which Sanskrit word is the term Rajput derived?"},"options":{"hi":["राजधर्म","राजपुत्र","राजमार्ग","राजकार्य"],"en":["Rajdharma","Rajaputra","Rajmarg","Rajkarya"]}},{"id":"nmms-c8-h1-q22","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"राजपुत्र शब्द का अर्थ क्या है?","en":"What does the word Rajaputra mean?"},"options":{"hi":["शासक का पुत्र","गाँव का मुखिया","धार्मिक शिक्षक","व्यापारी"],"en":["Son of a ruler","Village head","Religious teacher","Trader"]}},{"id":"nmms-c8-h1-q23","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"मध्यकाल में लेखक और सचिव के रूप में कौन-सा समूह महत्वपूर्ण हुआ?","en":"Which group became important as writers and administrators in the medieval period?"},"options":{"hi":["कायस्थ","वनवासी","नाविक","केवल कारीगर"],"en":["Kayasthas","Forest-dwellers","Sailors","Only artisans"]}},{"id":"nmms-c8-h1-q24","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"जाति पंचायत क्या थी?","en":"What was a caste panchayat?"},"options":{"hi":["किसी जाति के बुजुर्गों की सभा","शाही सेना","व्यापारिक जहाज","धार्मिक भवन"],"en":["An assembly of elders of a caste","A royal army","A trading ship","A religious building"]}},{"id":"nmms-c8-h1-q25","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"जाति के सदस्यों के आचरण को नियंत्रित करने में किसकी भूमिका थी?","en":"Which body played a role in regulating the conduct of caste members?"},"options":{"hi":["जाति पंचायत","केवल विदेशी व्यापारी","यूरोपीय नाविक","मानचित्रकार"],"en":["Caste panchayat","Only foreign traders","European sailors","Cartographers"]}},{"id":"nmms-c8-h1-q26","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"मध्यकाल में सिंचाई के लिए किस तकनीक का उपयोग किया जाता था?","en":"Which technology was used for irrigation in the medieval period?"},"options":{"hi":["चरखा","फ़ारसी चक्र","मुद्रण यंत्र","दूरबीन"],"en":["Spinning wheel","Persian wheel","Printing press","Telescope"]}},{"id":"nmms-c8-h1-q27","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"किस तकनीक ने सूत कातने की प्रक्रिया को बेहतर बनाया?","en":"Which device improved the process of spinning yarn?"},"options":{"hi":["फ़ारसी चक्र","चरखा","दिशा सूचक यंत्र","भाप इंजन"],"en":["Persian wheel","Spinning wheel","Compass","Steam engine"]}},{"id":"nmms-c8-h1-q28","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"इस काल से संबंधित सैन्य तकनीक कौन-सी थी?","en":"Which of the following was a military technology associated with this period?"},"options":{"hi":["आग्नेयास्त्र","मुद्रण यंत्र","विद्युत मोटर","हवाई जहाज"],"en":["Firearms","Printing press","Electric motor","Aeroplane"]}},{"id":"nmms-c8-h1-q29","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"अध्याय में उल्लिखित इस काल के दौरान उपमहाद्वीप में आई फसलों का कौन-सा समूह है?","en":"Which group of crops mentioned in the chapter reached the subcontinent during this period?"},"options":{"hi":["आलू, मक्का और मिर्च","केवल गेहूँ, जौ और चावल","केवल सरसों, चना और दालें","केवल कपास, जूट और गन्ना"],"en":["Potato, maize and chilli","Only wheat, barley and rice","Only mustard, gram and pulses","Only cotton, jute and sugarcane"]}},{"id":"nmms-c8-h1-q30","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"निम्नलिखित में से कौन-सा युग्म सही है?","en":"Which of the following pairs is correctly matched?"},"options":{"hi":["फ़ारसी चक्र — बुनाई","चरखा — सिंचाई","फ़ारसी चक्र — सिंचाई","आग्नेयास्त्र — पांडुलिपि नकल"],"en":["Persian wheel — Weaving","Spinning wheel — Irrigation","Persian wheel — Irrigation","Firearms — Manuscript copying"]}},{"id":"nmms-c8-h1-q31","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"1318 में भारतीय उपमहाद्वीप की विभिन्न क्षेत्रीय भाषाओं का उल्लेख किसने किया?","en":"Who referred to different regional languages of the Indian subcontinent in 1318?"},"options":{"hi":["अमीर खुसरो","अल-इदरीसी","मिनहाज-ए-सिराज","बाबर"],"en":["Amir Khusrau","Al-Idrisi","Minhaj-i-Siraj","Babur"]}},{"id":"nmms-c8-h1-q32","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"निम्नलिखित में से किस भाषा का उल्लेख अमीर खुसरो ने किया था?","en":"Which of the following languages was mentioned by Amir Khusrau?"},"options":{"hi":["अवधी","सिंधी","कश्मीरी","उपर्युक्त सभी"],"en":["Awadhi","Sindhi","Kashmiri","All of the above"]}},{"id":"nmms-c8-h1-q33","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"इस काल का प्रमुख धार्मिक विकास कौन-सा था?","en":"Which was an important religious development of this period?"},"options":{"hi":["भक्ति परंपराओं का विकास","मंदिरों का पूर्ण अंत","सभी धार्मिक प्रथाओं का अंत","सभी क्षेत्रीय परंपराओं का अंत"],"en":["Development of Bhakti traditions","Complete disappearance of temples","End of all religious practices","End of all regional traditions"]}},{"id":"nmms-c8-h1-q34","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"भक्ति परंपरा का केंद्रीय विचार क्या है?","en":"What is the central idea of the Bhakti tradition?"},"options":{"hi":["ईश्वर के प्रति भक्ति और व्यक्तिगत संबंध","केवल सैनिक सेवा","विदेशी देशों के साथ व्यापार","मानचित्र बनाना"],"en":["Devotion to God and a personal relationship","Only military service","Trade with foreign countries","Map-making"]}},{"id":"nmms-c8-h1-q35","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"इस काल के धार्मिक परिवर्तनों के बारे में कौन-सा कथन सही है?","en":"Which statement about religious changes during this period is correct?"},"options":{"hi":["कोई नई धार्मिक परंपरा विकसित नहीं हुई","पूजा के नए रूपों और भक्ति परंपराओं का विकास हुआ","सभी मंदिर छोड़ दिए गए","धर्म का समाज से कोई संबंध नहीं था"],"en":["No new religious traditions developed","New forms of worship and Bhakti traditions developed","All temples were abandoned","Religion had no connection with society"]}},{"id":"nmms-c8-h1-q36","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"उन्नीसवीं शताब्दी में भारतीय इतिहास को हिंदू, मुस्लिम और ब्रिटिश काल में किसने विभाजित किया?","en":"Who divided Indian history into Hindu, Muslim and British periods in the nineteenth century?"},"options":{"hi":["जेम्स मिल","अमीर खुसरो","अल-इदरीसी","बाबर"],"en":["James Mill","Amir Khusrau","Al-Idrisi","Babur"]}},{"id":"nmms-c8-h1-q37","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"भारतीय इतिहास के हिंदू, मुस्लिम और ब्रिटिश काल-विभाजन की आलोचना क्यों की जाती है?","en":"Why is the division of Indian history into Hindu, Muslim and British periods criticised?"},"options":{"hi":["यह आर्थिक परिवर्तनों को बहुत अधिक महत्व देता है","यह शासकों के धर्म को ऐतिहासिक काल-विभाजन का मुख्य आधार मानता है","यह सभी सामाजिक समूहों का समान अध्ययन करता है","यह शासकों के अस्तित्व की उपेक्षा करता है"],"en":["It gives too much importance to economic changes","It treats rulers'' religion as the main basis for periodisation","It studies all social groups equally","It ignores the existence of rulers"]}},{"id":"nmms-c8-h1-q38","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"एक हजार वर्षों में हुए परिवर्तनों का अध्ययन करने का सबसे उपयुक्त तरीका कौन-सा है?","en":"What is the most appropriate way to study changes over a thousand years?"},"options":{"hi":["केवल राजाओं और युद्धों का अध्ययन","केवल धार्मिक मान्यताओं का अध्ययन","विभिन्न स्रोतों से राजनीतिक, सामाजिक, आर्थिक और सांस्कृतिक परिवर्तनों का अध्ययन","केवल आधुनिक मानचित्रों का अध्ययन"],"en":["Studying only kings and wars","Studying only religious beliefs","Studying political, social, economic and cultural changes through different sources","Studying only modern maps"]}},{"id":"nmms-c8-h1-q39","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"इतिहासकारों को पांडुलिपियों के विभिन्न संस्करणों की तुलना क्यों करनी चाहिए?","en":"Why should historians compare different versions of manuscripts?"},"options":{"hi":["नकल के दौरान हुए अंतरों को पहचानने और मूल पाठ का पुनर्निर्माण करने के लिए","सभी ऐतिहासिक तथ्यों को बदलने के लिए","अतीत का अध्ययन न करने के लिए","पांडुलिपियों को मानचित्रों में बदलने के लिए"],"en":["To identify copying differences and reconstruct the original text","To change all historical facts","To avoid studying the past","To turn manuscripts into maps"]}},{"id":"nmms-c8-h1-q40","chapter":"अध्याय 1: एक हजार वर्षों में हुए परिवर्तन","question":{"hi":"इस अध्याय से मिलने वाली सबसे महत्वपूर्ण सीख क्या है?","en":"What is the most important lesson of this chapter?"},"options":{"hi":["समाज में कभी परिवर्तन नहीं होता","शब्दों के अर्थ हमेशा समान रहते हैं","ऐतिहासिक ज्ञान और समाज समय के साथ बदलते हैं तथा स्रोतों की संदर्भ के अनुसार व्याख्या करनी चाहिए","केवल शासक इतिहास बनाते हैं"],"en":["Society never changes","Words always retain the same meanings","Historical knowledge and society change over time, and sources must be interpreted in context","Only rulers make history"]}}]'::jsonb,1,true) on conflict (id) do update set title=excluded.title,class_level=excluded.class_level,subject=excluded.subject,chapter=excluded.chapter,duration_minutes=excluded.duration_minutes,total_marks=excluded.total_marks,questions=excluded.questions,attempt_limit=excluded.attempt_limit,is_published=excluded.is_published,updated_at=now();
